1	package com.maritime.platform.gateway.security.jwt;
2	
3	import com.maritime.platform.gateway.security.GatewaySecurityProperties;
4	import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
5	import org.springframework.data.redis.core.ReactiveRedisOperations;
6	import org.springframework.stereotype.Component;
7	import org.springframework.util.StringUtils;
8	import reactor.core.publisher.Mono;
9	
10	/**
11	 * Validates JWT principal state against Redis: session existence,
12	 * token blacklist membership, and user enabled status.
13	 *
14	 * <p>Each check is independently toggled via
15	 * {@link GatewaySecurityProperties.Validation}. All checks are
16	 * reactive and non-blocking.
17	 */
18	@Component
19	@ConditionalOnProperty("maritime.gateway.security.jwt.enabled")
20	public class JwtStateValidator {
21	
22	    private final ReactiveRedisOperations<String, String> redisOps;
23	    private final boolean requireSession;
24	    private final boolean checkBlacklist;
25	    private final boolean checkUserEnabled;
26	    private final String userEnabledDisabledValue;
27	    private final String sessionPrefix;
28	    private final String blacklistPrefix;
29	    private final String userEnabledPrefix;
30	
31	    public JwtStateValidator(ReactiveRedisOperations<String, String> redisOps,
32	            GatewaySecurityProperties properties) {
33	        this.redisOps = redisOps;
34	        GatewaySecurityProperties.Validation validation = properties.getJwt().getValidation();
35	        GatewaySecurityProperties.RedisKeys redisKeys = properties.getJwt().getRedisKeys();
36	        this.requireSession = validation.isRequireSession();
37	        this.checkBlacklist = validation.isCheckBlacklist();
38	        this.checkUserEnabled = validation.isCheckUserEnabled();
39	        this.userEnabledDisabledValue = validation.getUserEnabledDisabledValue();
40	        this.sessionPrefix = redisKeys.getSessionPrefix();
41	        this.blacklistPrefix = redisKeys.getBlacklistPrefix();
42	        this.userEnabledPrefix = redisKeys.getUserEnabledPrefix();
43	    }
44	
45	    /**
46	     * Validate session, blacklist, and user-enabled state against Redis.
47	     *
48	     * @param sessionId the session ID from JWT claims
49	     * @param jti       the JWT ID (jti claim), may be null
50	     * @param userId    the user ID from JWT claims
51	     * @return empty Mono on success, error Mono with {@link JwtAuthenticationException} on failure
52	     */
53	    public Mono<Void> validate(String sessionId, String jti, String userId) {
54	        return validateSession(sessionId)
55	                .then(Mono.defer(() -> validateBlacklist(jti)))
56	                .then(Mono.defer(() -> validateUserEnabled(userId)));
57	    }
58	
59	    private Mono<Void> validateSession(String sessionId) {
60	        if (!requireSession) {
61	            return Mono.empty();
62	        }
63	        return redisOps.hasKey(sessionPrefix + sessionId)
64	                .flatMap(exists -> {
65	                    if (Boolean.TRUE.equals(exists)) {
66	                        return Mono.empty();
67	                    }
68	                    return Mono.error(new JwtAuthenticationException(
69	                            GatewayAuthErrorCode.SESSION_EXPIRED,
70	                            "Session expired or does not exist: " + sessionId));
71	                });
72	    }
73	
74	    private Mono<Void> validateBlacklist(String jti) {
75	        if (!checkBlacklist || !StringUtils.hasText(jti)) {
76	            return Mono.empty();
77	        }
78	        return redisOps.hasKey(blacklistPrefix + jti)
79	                .flatMap(exists -> {
80	                    if (Boolean.TRUE.equals(exists)) {
81	                        return Mono.error(new JwtAuthenticationException(
82	                                GatewayAuthErrorCode.TOKEN_BLACKLISTED,
83	                                "Token has been blacklisted: " + jti));
84	                    }
85	                    return Mono.empty();
86	                });
87	    }
88	
89	    private Mono<Void> validateUserEnabled(String userId) {
90	        if (!checkUserEnabled) {
91	            return Mono.empty();
92	        }
93	        return redisOps.opsForValue().get(userEnabledPrefix + userId)
94	                .flatMap(value -> {
95	                    if (userEnabledDisabledValue.equals(value)) {
96	                        return Mono.error(new JwtAuthenticationException(
97	                                GatewayAuthErrorCode.USER_DISABLED,
98	                                "User is disabled: " + userId));
99	                    }
100	                    return Mono.empty();
101	                })
102	                .then();
103	    }
104	}
