5	/**
6	 * Externalized JWT configuration bound to {@code iam.security.jwt.*}.
7	 */
8	@ConfigurationProperties(prefix = "iam.security.jwt")
9	public class JwtProperties {
10	
11	    private String secret = "iam-center-default-jwt-secret-key-change-in-production!";
12	
13	    private long accessTokenExpirationMinutes = 30;
14	
15	    private long refreshTokenExpirationHours = 24;
16	
17	    private String issuer = "iam-center";
18	
19	    public String getSecret() {
20	        return secret;
21	    }
22	
23	    public void setSecret(String secret) {
24	        this.secret = secret;
25	    }
26	
27	    public long getAccessTokenExpirationMinutes() {
28	        return accessTokenExpirationMinutes;
29	    }
30	
31	    public void setAccessTokenExpirationMinutes(long accessTokenExpirationMinutes) {
32	        this.accessTokenExpirationMinutes = accessTokenExpirationMinutes;
33	    }
34	
35	    public long getRefreshTokenExpirationHours() {
36	        return refreshTokenExpirationHours;
37	    }
38	
39	    public void setRefreshTokenExpirationHours(long refreshTokenExpirationHours) {
40	        this.refreshTokenExpirationHours = refreshTokenExpirationHours;
41	    }
