21	 *
22	 * <p>Derives the AES key from the JWT shared secret via
23	 * SHA-256, so no additional key management is needed.
24	 */
25	public final class JwtEncryptor {
26	
27		private static final String AES_GCM = "AES/GCM/NoPadding";
28		private static final int IV_LENGTH = 12;
29		private static final int TAG_LENGTH_BITS = 128;
30		private static final SecureRandom RANDOM = new SecureRandom();
31	
32		private final SecretKey aesKey;
33	
34		public JwtEncryptor(String jwtSecret) {
35			this.aesKey = deriveKey(jwtSecret);
36		}
37	
38		public String encrypt(String jwt) {
39			try {
40				byte[] plaintext = jwt.getBytes(StandardCharsets.UTF_8);
41				byte[] iv = new byte[IV_LENGTH];
42				RANDOM.nextBytes(iv);
43	
44				Cipher cipher = Cipher.getInstance(AES_GCM);
45				cipher.init(Cipher.ENCRYPT_MODE, aesKey,
46						new GCMParameterSpec(TAG_LENGTH_BITS, iv));
47				byte[] ciphertext = cipher.doFinal(plaintext);
48	
49				ByteBuffer buffer = ByteBuffer.allocate(IV_LENGTH + ciphertext.length);
50				buffer.put(iv);
51				buffer.put(ciphertext);
52	
53				return Base64.getUrlEncoder().withoutPadding()
54						.encodeToString(buffer.array());
55			} catch (Exception e) {
56				throw new IllegalStateException("JWT encryption failed", e);
57			}
58		}
59	
60		public String decrypt(String encryptedToken) {
61			try {
62				byte[] decoded = Base64.getUrlDecoder().decode(encryptedToken);
63				if (decoded.length < IV_LENGTH + 1) {
64					return null;
65				}
66	
67				ByteBuffer buffer = ByteBuffer.wrap(decoded);
68				byte[] iv = new byte[IV_LENGTH];
69				buffer.get(iv);
70				byte[] ciphertext = new byte[buffer.remaining()];
71				buffer.get(ciphertext);
72	
73				Cipher cipher = Cipher.getInstance(AES_GCM);
74				cipher.init(Cipher.DECRYPT_MODE, aesKey,
75						new GCMParameterSpec(TAG_LENGTH_BITS, iv));
76				byte[] plaintext = cipher.doFinal(ciphertext);
77	
78				return new String(plaintext, StandardCharsets.UTF_8);
79			} catch (Exception e) {
80				return null;
81			}
82		}
83	
84		private static SecretKey deriveKey(String secret) {
85			try {
86				MessageDigest sha256 = MessageDigest.getInstance("SHA-256");
87				byte[] keyBytes = sha256.digest(secret.getBytes(StandardCharsets.UTF_8));
88				return new SecretKeySpec(keyBytes, "AES");
89			} catch (Exception e) {
90				throw new IllegalStateException("AES key derivation failed", e);
91			}
92		}
93	}
