        @Test
        @DisplayName("JWT_OR_HMAC auth mode via programmatic route policy")
        void jwtOrHmacMode() {
            GatewaySecurityProperties props = new GatewaySecurityProperties();
            props.setDefaultAuthMode(AuthMode.NONE);

